<script setup lang="ts">import {useAcademyDonations,type AcademyDonation} from '~/composables/useAcademyDonations'; definePageMeta({layout:'main',middleware:'auth'});const {fetchMyDonations}=useAcademyDonations();const rows=ref<AcademyDonation[]>([]),meta=ref<any>({}),loading=ref(true);const load=async(p=1)=>{loading.value=true;try{const r=await fetchMyDonations({page:p});rows.value=r.data;meta.value=r.meta}finally{loading.value=false}};onMounted(()=>load());const amount=(r:AcademyDonation)=>r.donation_type==='point'?`${r.points_amount??0} points`:`${r.cash_amount??0} ${r.currency||'THB'}`</script>
<template><div class="mx-auto max-w-6xl space-y-6 p-6"><h1 class="text-2xl font-bold">Academy donations</h1><div class="overflow-hidden rounded-2xl bg-white shadow dark:bg-slate-800"><div class="overflow-x-auto"><table class="w-full text-left text-sm"><thead class="bg-slate-50"><tr><th class="p-4">Date</th><th class="p-4">Academy</th><th class="p-4">Type</th><th class="p-4">Amount</th><th class="p-4">Status</th><th class="p-4">Purpose</th></tr></thead><tbody><tr v-if="loading"><td colspan="6" class="p-8 text-center">Loading…</td></tr><tr v-else-if="!rows.length"><td colspan="6" class="p-8 text-center">No donations yet.</td></tr><tr v-for="r in rows" :key="r.id" class="border-t"><td class="p-4">{{new Date(r.created_at).toLocaleDateString()}}</td><td class="p-4">{{r.academy?.name||`Academy #${r.academy_id}`}}</td><td class="p-4">{{r.donation_type}}</td><td class="p-4">{{amount(r)}}</td><td class="p-4">{{r.status}}</td><td class="max-w-xs truncate p-4">{{r.purpose||'—'}}</td></tr></tbody></table></div></div><div class="flex justify-center gap-4"><button v-if="meta.current_page>1" @click="load(meta.current_page-1)">Previous</button><span>{{meta.current_page||1}}</span><button v-if="meta.current_page<meta.last_page" @click="load(meta.current_page+1)">Next</button></div></div></template>
